local StringWinderMaker = {}
local PRODUCTS = {
    iron_stringwinder = { name = "Železni navijalec strun", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni navijalec strun za glasbila." },
    bronze_stringwinder = { name = "Bronast navijalec strun", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast navijalec strun za fino glasbo." },
    silver_stringwinder = { name = "Srebrn navijalec strun", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn navijalec strun za plemiške glasbenike." },
    gilded_stringwinder = { name = "Pozlačen navijalec strun", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen navijalec strun za dvorne glasbenike." },
    jewel_set_stringwinder = { name = "Draguljast navijalec strun", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast navijalec strun za kraljevske glasbenike." },
    royal_sovereign_stringwinder = { name = "Kraljevski suveren navijalec strun", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren navijalec strun z biseri za krono." },
}
local BUILDINGS = {
    stringwinder_workshop = { name = "Stringwinder delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    stringwinder_house = { name = "Stringwinder hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_stringwinder_atelier = { name = "Mojstrski stringwinder atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_stringwinder_palace = { name = "Suverena stringwinder palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
StringWinderMaker.ironStock = 14; StringWinderMaker.bronzeStock = 12; StringWinderMaker.woodStock = 14; StringWinderMaker.leatherStock = 10; StringWinderMaker.silverStock = 8; StringWinderMaker.goldStock = 6; StringWinderMaker.jewelStock = 4; StringWinderMaker.pearlStock = 4
StringWinderMaker.productStock = {}; StringWinderMaker.buildings = {}; StringWinderMaker.maker = nil; StringWinderMaker.activeMaking = {}; StringWinderMaker.totalProducts = 0; StringWinderMaker.dayTimer = 0
function StringWinderMaker.init() StringWinderMaker.ironStock=14; StringWinderMaker.bronzeStock=12; StringWinderMaker.woodStock=14; StringWinderMaker.leatherStock=10; StringWinderMaker.silverStock=8; StringWinderMaker.goldStock=6; StringWinderMaker.jewelStock=4; StringWinderMaker.pearlStock=4; StringWinderMaker.productStock={}; StringWinderMaker.buildings={}; StringWinderMaker.maker=nil; StringWinderMaker.activeMaking={}; StringWinderMaker.totalProducts=0; StringWinderMaker.dayTimer=0; print("[StringWinderMaker] Royal String Winder Maker System initialized (6 products, 4 buildings)") end
function StringWinderMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; StringWinderMaker.maker={name=n or ("Navijalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Navijalec najet: %s (spretnost: %d)",StringWinderMaker.maker.name,s),"success") end; return true end
function StringWinderMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function StringWinderMaker.build(id) local ok,e=StringWinderMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(StringWinderMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function StringWinderMaker.getQualityBonus() local b=0; for _,bd in ipairs(StringWinderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function StringWinderMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and StringWinderMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and StringWinderMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and StringWinderMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and StringWinderMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and StringWinderMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and StringWinderMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and StringWinderMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and StringWinderMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #StringWinderMaker.buildings==0 then return false,"Potrebna navijalna delavnica" end; if not StringWinderMaker.maker then return false,"Potreben navijalec" end; return true end
function StringWinderMaker.make(pt,qty) qty=qty or 1; local ok,e=StringWinderMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then StringWinderMaker.ironStock=StringWinderMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then StringWinderMaker.bronzeStock=StringWinderMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then StringWinderMaker.woodStock=StringWinderMaker.woodStock-d.woodCost*qty end; if d.leatherCost then StringWinderMaker.leatherStock=StringWinderMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then StringWinderMaker.silverStock=StringWinderMaker.silverStock-d.silverCost*qty end; if d.goldCost then StringWinderMaker.goldStock=StringWinderMaker.goldStock-d.goldCost*qty end; if d.jewelCost then StringWinderMaker.jewelStock=StringWinderMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then StringWinderMaker.pearlStock=StringWinderMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if StringWinderMaker.maker then t=math.max(1,t-math.floor(StringWinderMaker.maker.skill/13)) end; table.insert(StringWinderMaker.activeMaking,{id="stringwinder_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function StringWinderMaker.completeMaking(m) local q=1.0+(StringWinderMaker.getQualityBonus()/100); if StringWinderMaker.maker then q=q+(StringWinderMaker.maker.skill/140) end; q=math.min(2.5,q); StringWinderMaker.productStock[m.productType]=(StringWinderMaker.productStock[m.productType] or 0)+m.quantity; StringWinderMaker.totalProducts=StringWinderMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if StringWinderMaker.maker then StringWinderMaker.maker.itemsMade=StringWinderMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then StringWinderMaker.maker.skill=math.min(100,StringWinderMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Navijalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"stringwinder.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function StringWinderMaker.update(dt) if not _G.state then return end; StringWinderMaker.dayTimer=StringWinderMaker.dayTimer+dt; if StringWinderMaker.dayTimer>=30 then StringWinderMaker.dayTimer=0; for i=#StringWinderMaker.activeMaking,1,-1 do local m=StringWinderMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then StringWinderMaker.completeMaking(m); table.remove(StringWinderMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(StringWinderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if StringWinderMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function StringWinderMaker.getStats() return {ironStock=StringWinderMaker.ironStock,bronzeStock=StringWinderMaker.bronzeStock,woodStock=StringWinderMaker.woodStock,leatherStock=StringWinderMaker.leatherStock,silverStock=StringWinderMaker.silverStock,goldStock=StringWinderMaker.goldStock,jewelStock=StringWinderMaker.jewelStock,pearlStock=StringWinderMaker.pearlStock,productStock=StringWinderMaker.productStock,numBuildings=#StringWinderMaker.buildings,hasMaker=StringWinderMaker.maker~=nil,makerName=StringWinderMaker.maker and StringWinderMaker.maker.name or "—",makerSkill=StringWinderMaker.maker and StringWinderMaker.maker.skill or 0,activeMaking=#StringWinderMaker.activeMaking,totalProducts=StringWinderMaker.totalProducts} end
return StringWinderMaker
